#[derive(Debug, Clone, Component)]
pub struct LoginPage {
    base: WebElement,
    #[by(css = "#user")] user: ElementResolver<WebElement>,
    #[by(css = "#pass")] pass: ElementResolver<WebElement>,
}
impl LoginPage {
    pub async fn login(&self, u: &str, p: &str) -> WebDriverResult<()> {
        self.user.resolve().await?.send_keys(u).await?;
        self.pass.resolve().await?.send_keys(p).await?;
        Ok(())
    }
}
